#include <filesystem>
#include <iostream>
#include <string>
#include <string_view>
#include <vector>

#include "filehash.h"
#include "merkle.h"

namespace {

// hash/root 共用的文件参数解析规则：
//  * 第一个单独的 "--" 是选项结束标记，它本身不算文件；
//  * 结束标记之前，凡是以连字符开头的参数都按选项解释；这两个命令不支持
//    任何选项，因此一律构成用法错误（即使同名文件可以读取）；
//  * 结束标记之后的所有参数一律是文件路径（包括 "-notes.bin"、"--version"、
//    单独的 "-" 以及再次出现的 "--"），按字面定位真实文件。
struct FileArgs {
    std::vector<std::filesystem::path> files;
    std::string unsupported;  // 遇到的不支持选项原文；非空即用法错误
};

FileArgs parse_file_args(char* const* argv, int first, int last) {
    FileArgs args;
    bool options_ended = false;
    for (int i = first; i < last; ++i) {
        const std::string_view arg{argv[i]};
        if (!options_ended && arg == "--") {
            options_ended = true;
            continue;  // 结束标记本身不占文件位置
        }
        if (!options_ended && !arg.empty() && arg.front() == '-') {
            // 立即返回：批次中即使还有正常文件，也不能继续产出结果。
            args.unsupported = std::string{arg};
            return args;
        }
        args.files.emplace_back(argv[i]);
    }
    return args;
}

void print_hash_usage() {
    std::cerr << "Usage: branchaudit hash [--] <file>\n";
}

void print_root_usage() {
    std::cerr << "Usage: branchaudit root [--] [<file>...]\n";
}

void print_usage() {
    std::cerr << "Usage: branchaudit --version\n"
                 "       branchaudit hash [--] <file>\n"
                 "       branchaudit root [--] [<file>...]\n";
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << "branchaudit 0.1.0\n";
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "hash") {
        const FileArgs args = parse_file_args(argv, 2, argc);
        if (!args.unsupported.empty()) {
            std::cerr << "branchaudit hash: unsupported option '"
                      << args.unsupported << "'\n";
            print_hash_usage();
            return 2;
        }
        // 扣除结束标记后，hash 恰好接受一个文件；缺失或多给都属于用法错误。
        if (args.files.size() != 1) {
            std::cerr << "branchaudit hash: expected exactly one file, got "
                      << args.files.size() << '\n';
            print_hash_usage();
            return 2;
        }
        const branchaudit::FileHashResult result =
            branchaudit::sha256_file(args.files.front());
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    if (argc >= 2 && std::string_view(argv[1]) == "root") {
        const FileArgs args = parse_file_args(argv, 2, argc);
        if (!args.unsupported.empty()) {
            std::cerr << "branchaudit root: unsupported option '"
                      << args.unsupported << "'\n";
            print_root_usage();
            return 2;
        }
        // root 接受零个或多个文件，顺序即命令行参数顺序：不排序、不去重。
        // 仅给结束标记时 files 为空，返回空批次根。
        const branchaudit::FileHashResult result =
            branchaudit::merkle_root_files(args.files);
        if (!result.ok()) {
            std::cerr << "branchaudit: " << result.error << '\n';
            return 1;
        }
        std::cout << branchaudit::to_hex(result.digest) << '\n';
        return 0;
    }

    print_usage();
    return 2;
}

#pragma once

#include <array>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <vector>

#include "filehash.h"
#include "sha256.h"

namespace branchaudit {

// 32 字节原始摘要。Merkle 各层组合一律使用原始字节，不使用十六进制文本。
using Digest = std::array<std::uint8_t, Sha256::kDigestSize>;

// 空批次根：SHA-256 对空字节序列。
// 注意它与“单个空文件”的叶子摘要不同（叶子带 0x00 前缀）。
Digest merkle_empty_root();

// 文件叶子：SHA-256(0x00 || data)。
// 0x00 是值为 0x00 的单个原始前缀字节，不是字符串；data 为文件全部原始字节。
// 供已知字节内容时直接组合使用；文件请用流式的 merkle_root_files。
Digest merkle_leaf(const unsigned char* data, std::size_t size);

// 父摘要：SHA-256(0x01 || left || right)。
// 0x01 是值为 0x01 的单个原始前缀字节，left/right 各为 32 个原始字节，
// 先左后右，顺序不可交换。
Digest merkle_parent(const Digest& left, const Digest& right);

// 计算一个有序文件批次的 Merkle 根。
//
// 位置顺序完全取自 paths 的下标：不按文件名或摘要排序，也不去重；
// 同一路径重复出现、多个文件内容相同，都各自保留独立位置。根只反映各位置
// 的文件内容，不包含任何路径文字。
//
// 配对规则：每层相邻节点先左后右两两配对；若该层节点数为奇数，最后一个
// 节点没有伙伴，其摘要原样提升到上一层，不复制、不补零，直到只剩一个根。
// 只有一个文件时根即其叶子摘要；paths 为空时返回 merkle_empty_root()。
//
// 叶子按流式计算（固定缓冲），内存占用与文件大小无关。任一文件不存在、
// 指向目录、无法打开或读取失败时，整次计算失败：返回 error 非空的结果，
// 说明失败的路径和原因，不用其余文件产出部分结果。不打印、不退出进程。
FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths);

}  // namespace branchaudit

