28	namespace internal {
29	
30	FileHashResult sha256_file_digest(const std::filesystem::path& path,
31	                                  const unsigned char* prefix_byte) {
32	    FileHashResult result;
33	
34	    std::error_code ec;
35	    if (std::filesystem::is_directory(path, ec)) {
36	        result.error = path.string() + ": is a directory";
37	        return result;
38	    }
39	
40	    errno = 0;
41	    std::ifstream in(path, std::ios::binary);
42	    if (!in.is_open()) {
43	        const int saved_errno = errno;
44	        result.error = path.string() + ": " +
45	                       (saved_errno != 0
46	                            ? std::strerror(saved_errno)
47	                            : "cannot open file");
48	        return result;
49	    }
50	
51	    Sha256 sha;
52	    // 可选的单个前缀字节：在任何文件字节之前恰好参与一次（叶子为 0x00），
53	    // 空文件时也存在；放在读取循环之外，不会随分块重复加入。
54	    if (prefix_byte != nullptr) {
55	        sha.update(prefix_byte, 1);
56	    }
57	    // 固定大小缓冲区流式读取，内存占用不随文件长度增长。
58	    char buffer[64 * 1024];
59	    while (in) {
60	        in.read(buffer, sizeof(buffer));
61	        const std::streamsize count = in.gcount();
62	        if (count > 0) {
63	            sha.update(reinterpret_cast<const unsigned char*>(buffer),
64	                       static_cast<std::size_t>(count));
65	        }
66	    }
67	    if (in.bad()) {
68	        const int saved_errno = errno;
69	        result.error = path.string() + ": read error" +
70	                       (saved_errno != 0
71	                            ? std::string(": ") + std::strerror(saved_errno)
72	                            : std::string());
73	        return result;
74	    }
75	
76	    result.digest = sha.final();
77	    return result;
78	}
79	
80	}  // namespace internal
81	
82	}  // namespace branchaudit
