370	    const fs::path bad = tmp.root / "present 出错.bin";
371	    const fs::path empty = tmp.root / "empty 空.bin";
372	    constexpr long kPartial = 40;
373	    const auto good_bytes1 = bytes_of("normal-file-one");
374	    const auto good_bytes2 = bytes_of("normal-file-two");
375	    const auto bad_bytes = pattern(200);
376	    write_file(good1, good_bytes1);
377	    write_file(good2, good_bytes2);
378	    write_file(bad, bad_bytes);
379	    write_file(empty, {});
380	
381	    const Digest good_leaf1 = leaf_bytes(good_bytes1);
382	    const Digest good_leaf2 = leaf_bytes(good_bytes2);
383	    const Digest bad_partial_leaf =
384	        branchaudit::merkle_leaf(bad_bytes.data(),
385	                                 static_cast<std::size_t>(kPartial));
386	
387	    // 夹具在无注入时必须成功，排除“写死错误结果”的可能。
388	    check(hex_of(root_of({good1, bad, good2})).size() == 64,
389	          "iofail fixtures: batch succeeds without injected fault");
390	
391	    // ---- 打开失败：唯一位置 --------------------------------------------
392	    {
393	        fault_test::FaultTrigger trigger(
394	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
395	        branchaudit::FileHashResult r;
396	        auto captured = silent_merkle({bad}, &r);
397	        check(!r.ok(), "unopenable leaf: batch fails");
398	        check(r.error.find(bad.string()) != std::string::npos,
399	              "unopenable leaf: error names the failed file");
400	        check(r.error.find("ermission") != std::string::npos ||
401	                  r.error.find("denied") != std::string::npos ||
402	                  r.error.find("cces") != std::string::npos,
403	              "unopenable leaf: error states open/permission reason");
404	        check(captured.first.empty() && captured.second.empty(),
405	              "unopenable leaf: library prints nothing, does not exit");
406	    }
407	
408	    // ---- 打开失败：有序批次中出错前已经处理过正常文件 ------------------
409	    {
410	        fault_test::FaultTrigger trigger(
411	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
412	        branchaudit::FileHashResult r;
413	        auto captured = silent_merkle({good1, good2, bad}, &r);
414	        check(!r.ok(),
415	              "open failure after processed good files: whole batch fails");
416	        check(r.error.find(bad.string()) != std::string::npos,
417	              "open failure in batch: error points at the real failing file");
418	        check(r.error.find(good1.string()) == std::string::npos &&
419	                  r.error.find(good2.string()) == std::string::npos,
420	              "open failure in batch: already-processed files are not blamed");
421	        check(captured.first.empty(),
422	              "open failure in batch: no root of the processed prefix is printed");
423	        check(captured.second.empty(),
424	              "open failure in batch: library prints nothing");
425	        // 不得给出“仅前两个正常文件”的根。
426	        check(r.digest != branchaudit::merkle_parent(good_leaf1, good_leaf2),
427	              "open failure: root skipping the failing position is not returned");
428	        check(r.digest != good_leaf1,
429	              "open failure: a processed leaf is not returned as the root");
430	    }
431	
432	    // ---- 读取失败：叶子取得部分内容后继续读出错 ------------------------
433	    {
434	        fault_test::FaultTrigger trigger(
435	            "BRANCHAUDIT_TEST_READ_FAIL",
436	            bad.string() + ":" + std::to_string(kPartial));
437	        branchaudit::FileHashResult r;
438	        auto captured = silent_merkle({bad}, &r);
439	        check(!r.ok(), "read error mid-leaf: batch fails");
440	        check(r.error.find(bad.string()) != std::string::npos,
441	              "read failure: error names the failed file");
442	        check(r.error.find("read") != std::string::npos,
443	              "read failure: error says read failed rather than normal EOF");
444	        check(captured.first.empty() && captured.second.empty(),
445	              "read failure: library prints nothing");
446	        // 已读到的部分内容不能成为成功叶子摘要。
447	        check(r.digest != bad_partial_leaf,
448	              "read failure: partial leaf digest is not returned as success");
449	        check(r.digest != leaf_bytes(bad_bytes),
450	              "read failure: full-content leaf is not fabricated either");
451	    }
452	
453	    // ---- 读取失败：出错前正常文件已处理，仍整次失败且指向真正出错文件 --
454	    {
455	        fault_test::FaultTrigger trigger(
456	            "BRANCHAUDIT_TEST_READ_FAIL",
457	            bad.string() + ":" + std::to_string(kPartial));
458	        branchaudit::FileHashResult r;
459	        auto captured = silent_merkle({good1, bad, good2}, &r);
460	        check(!r.ok(),
461	              "read error after a good file: whole ordered batch fails");
462	        check(r.error.find(bad.string()) != std::string::npos,
463	              "batch read failure: error names the truly failing file");
464	        check(r.error.find(good1.string()) == std::string::npos &&
465	                  r.error.find(good2.string()) == std::string::npos,
466	              "batch read failure: good files are not named as the cause");
467	        check(captured.first.empty(),
468	              "batch read failure: no partial/skipped-position root is emitted");
469	        check(captured.second.empty(),
470	              "batch read failure: library prints nothing");
471	        check(r.digest != good_leaf1,
472	              "batch read failure: processed-prefix leaf is not a result");
473	    }
474	
475	    // ---- 空文件叶子在读取故障武装下仍正常读完 --------------------------
476	    {
477	        fault_test::FaultTrigger trigger(
478	            "BRANCHAUDIT_TEST_READ_FAIL",
479	            empty.string() + ":" + std::to_string(kPartial));
480	        branchaudit::FileHashResult r;
481	        auto captured = silent_merkle({empty}, &r);
482	        check(r.ok(),
483	              "empty file leaf reads to completion successfully (no content != error)");
484	        check(hex_of(r.digest) ==
485	                  "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
486	              "empty file leaf remains SHA-256(0x00)");
487	        check(captured.first.empty() && captured.second.empty(),
488	              "empty file leaf: library prints nothing");
489	    }
490	
491	    // ---- 故障只作用于指定路径：批次中其他文件不受影响 ------------------
492	    {
493	        fault_test::FaultTrigger trigger(
494	            "BRANCHAUDIT_TEST_READ_FAIL",
495	            bad.string() + ":" + std::to_string(kPartial));
496	        branchaudit::FileHashResult r;
497	        silent_merkle({good1, good2}, &r);
498	        check(r.ok() && r.digest == branchaudit::merkle_parent(good_leaf1, good_leaf2),
499	              "fault is path-scoped: batch without the named path is unaffected");
500	    }
501	}
502	
503	// ---- 大文件：流式读取、尾部敏感 -------------------------------------------
504	
505	void test_large_files() {
506	    TempArea tmp("large");
507	    const std::vector<unsigned char> big = fill_a(200000);
508	    const std::vector<unsigned char> pat = pattern(200000);
509	    const fs::path f_big = tmp.root / "a200000.bin";
510	    const fs::path f_pat = tmp.root / "pattern200000.bin";
511	    write_file(f_big, big);
512	    write_file(f_pat, pat);
513	
514	    check(hex_of(root_of({f_big})) ==
515	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
516	          "single large file leaf (streaming)");
517	    check(hex_of(root_of({f_big, f_pat})) ==
518	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
519	          "root [big, pattern]");
520	    check(hex_of(root_of({f_pat, f_big})) ==
521	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
522	          "root [pattern, big] differs under reversal");
523	
524	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
525	    std::vector<unsigned char> tail = big;
526	    tail.back() = static_cast<unsigned char>('b');
527	    const fs::path f_tail = tmp.root / "a200000tail.bin";
528	    write_file(f_tail, tail);
529	    check(hex_of(root_of({f_tail})) ==
530	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
531	          "large file: changing last byte changes leaf/root");
532	    check(root_of({f_tail}) != root_of({f_big}),
533	          "large file: tail change is detected");
534	}
535	
536	}  // namespace
537	
538	int main(int argc, char** argv) {
539	    fault_test::ensure_fault_preloaded(argc, argv);
540	
541	    test_empty_batch();
542	    test_leaf_rule();
543	    test_parent_rule();
544	    test_file_batches();
545	    test_relative_paths();
546	    test_failures();
547	    if (fault_test::kFaultInjectionAvailable) {
548	        test_io_failures();
549	    } else {
550	        // 平台无 LD_PRELOAD//proc 故障注入支持（如 macOS）：明确报告
551	        // 跳过，不计入已通过检查。
552	        ++g_skipped;
553	        std::cout << "SKIP: unopenable-leaf and mid-read-error checks "
554	                     "(fault injection not supported on this platform)\n";
555	    }
556	    test_large_files();
557	
558	    if (g_failures == 0) {
559	        std::cout << "all " << g_checks << " merkle regression checks passed";
560	        if (g_skipped > 0) {
561	            std::cout << " (" << g_skipped << " platform-specific check group"
562	                         " skipped, not verified)";
563	        }
564	        std::cout << '\n';
565	        return 0;
566	    }
567	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
568	    return 1;
569	}
