MerkleProofResult merkle_proof_file(const std::vector<std::filesystem::path>& paths,
                                    std::uint64_t leaf_index) {
    MerkleProofResult result;
    if (leaf_index >= paths.size()) {
        result.error = "leaf index " + std::to_string(leaf_index) +
                       " out of range for batch of " +
                       std::to_string(paths.size()) + " file(s)";
        return result;
    }

    std::vector<Digest> level;
    level.reserve(paths.size());
    for (const auto& path : paths) {
        FileHashResult leaf = leaf_file(path);
        if (!leaf.ok()) {
            result.error = std::move(leaf.error);
            return result;
        }
        level.push_back(leaf.digest);
    }

    result.proof.leaf_count = paths.size();
    result.proof.leaf_index = leaf_index;
    result.proof.leaf = level[leaf_index];

    std::size_t idx = static_cast<std::size_t>(leaf_index);
    while (level.size() > 1) {
        std::vector<Digest> next;
        const bool odd = (level.size() % 2) != 0;
        next.reserve(level.size() / 2 + (odd ? 1 : 0));
        // 记录当前节点在这一层的兄弟（若存在）。
        if (idx % 2 == 0) {
            if (idx + 1 < level.size()) {
                result.proof.siblings.push_back({MerkleSibling::Side::right, level[idx + 1]});
            }
            // idx 为奇数层末节点：原样提升，无兄弟记录。
        } else {
            result.proof.siblings.push_back({MerkleSibling::Side::left, level[idx - 1]});
        }
        for (std::size_t i = 0; i + 1 < level.size(); i += 2) {
            next.push_back(merkle_parent(level[i], level[i + 1]));
        }
        if (odd) {
            next.push_back(level.back());
        }
        idx /= 2;
        level = std::move(next);
    }

    result.proof.root = level.front();
    return result;
}
```

